sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // Query csm_consumer where user reference matches current csm_consumer_user
    var consumerGR = new GlideRecord('csm_consumer');
    consumerGR.addQuery('user', current.sys_id);
    consumerGR.query();
    if (consumerGR.next()) {
        // Update consumer fields with values from csm_consumer_user
        consumerGR.setValue('first_name', current.first_name);
        consumerGR.setValue('middle_name', current.middle_name);
        consumerGR.setValue('last_name', current.last_name);
        consumerGR.setValue('email', current.email);
        consumerGR.setValue('home_phone', current.home_phone);
        consumerGR.setValue('mobile_phone', current.mobile_phone);
        consumerGR.setValue('business_phone', current.phone); // Make sure 'phone' is the correct field
        consumerGR.update();
    } else {
        // Create a new consumer record if one does not exist
        var newConsumer = new GlideRecord('csm_consumer');
        newConsumer.initialize();
        newConsumer.user = current.sys_id;
        newConsumer.first_name = current.first_name;
        newConsumer.middle_name = current.middle_name;
        newConsumer.last_name = current.last_name;
        newConsumer.email = current.email;
        newConsumer.home_phone = current.home_phone;
        newConsumer.mobile_phone = current.mobile_phone;
        newConsumer.business_phone = current.phone;
        newConsumer.insert();
    }
})(current, previous);
